node -e "
const fs = require('fs');
const path = require('path');
const specs = ['specs/hal-engine-tool-input-validation/spec.md', 'specs/hal-engine-tool-registry/spec.md'];
let bad = 0, total = 0;
for (const spec of specs) {
  const text = fs.readFileSync(spec, 'utf8');
  const re = /\[validated by: ([^\]]+)\]\(([^)#]+)#L(\d+)\)/g;
  let m;
  while ((m = re.exec(text))) {
    total++;
    const [, title, rel, lineStr] = m;
    const file = path.resolve(path.dirname(spec), rel);
    const line = fs.readFileSync(file, 'utf8').split('\n')[Number(lineStr) - 1] ?? '';
    const tm = line.match(/it\('(.+?)'/) || line.match(/it\(\"(.+?)\"/);
    if (!tm || tm[1] !== title) { bad++; console.log('MISMATCH', spec, '#' + lineStr, JSON.stringify(title), '->', JSON.stringify(line.trim().slice(0, 90))); }
  }
}
console.log('checked', total, 'links;', bad, 'mismatches');
"
